const authSchema = z.object({ email:z.string().email('Enter a valid email address'), password:z.string().min(6,'Use at least 6 characters'), fullName:z.string().optional() });
type AuthValues = z.infer<typeof authSchema>;
export function AuthPage({ mode }: { mode:'login'|'register' }) {
  const { client, loading } = useAuth(); const [, navigate] = useLocation(); const { toast } = useToast();
  const form = useForm<AuthValues>({ resolver:zodResolver(authSchema), defaultValues:{email:'',password:'',fullName:''} });
  const submit = async (values:AuthValues) => {
    if (!client) { toast({title:'Authentication is unavailable',description:'Could not load secure sign-in settings. Please try again shortly.'}); return; }
    const result = mode==='register'
      ? await client.auth.signUp({email:values.email,password:values.password,options:{data:{full_name:values.fullName}}})
      : await client.auth.signInWithPassword({email:values.email,password:values.password});
    if (result.error) { toast({title:'Could not continue',description:result.error.message}); return; }
    if (mode==='register' && !result.data.session) { toast({title:'Check your inbox',description:'Confirm your email address, then return here to sign in.'}); navigate('/login'); return; }
    navigate('/dashboard');
  };
  return <div className="app-grain min-h-[100dvh] bg-[#f2efe5]"><header className="mx-auto flex max-w-[1240px] justify-between px-5 py-5 sm:px-10"><Brand/><Link href="/" className="flex items-center gap-2 text-sm font-semibold text-emerald-900/70"><ArrowLeft size={15}/> Back home</Link></header>
    <main className="mx-auto grid min-h-[calc(100dvh-80px)] max-w-[1240px] items-center gap-10 px-5 pb-12 pt-5 sm:px-10 md:grid-cols-[1fr_.8fr]">
      <div className="hidden max-w-xl md:block"><span className="text-[10px] font-bold uppercase tracking-[.22em] text-amber-700">A calm start to a better season</span><h1 className="mt-4 font-serif text-6xl leading-[.98] tracking-[-.03em]">{mode==='login'?'Welcome back to your field notes.':'Your farm deserves advice that knows it.'}</h1><p className="mt-6 max-w-md text-base leading-7 text-emerald-950/65">A place for your questions, your crop details and the small decisions that shape a growing season.</p><div className="mt-12 flex gap-3"><span className="grid size-11 place-items-center rounded-2xl bg-emerald-900 text-amber-200"><Sprout size={22}/></span><div><p className="text-sm font-semibold">Private by design</p><p className="mt-1 text-xs text-muted-foreground">Your account keeps your workspace yours.</p></div></div></div>
      <div className="mx-auto w-full max-w-[460px] rounded-[1.7rem] border border-emerald-950/10 bg-[#fbfaf5] p-6 shadow-[0_20px_60px_rgba(32,60,42,.09)] sm:p-9">
        <p className="text-xs font-bold uppercase tracking-[.18em] text-emerald-700">{mode==='login'?'Your workspace':'Let’s get started'}</p><h2 className="mt-2 font-serif text-3xl">{mode==='login'?'Sign in':'Create your account'}</h2><p className="mt-2 text-sm text-muted-foreground">{mode==='login'?'Pick up where your farm left off.':'A few details now. More personal advice later.'}</p>
        <Form {...form}><form onSubmit={form.handleSubmit(submit)} className="mt-7 space-y-4">
          {mode==='register'&&<FormField control={form.control} name="fullName" render={({field})=><FormItem><FormLabel>Your name</FormLabel><FormControl><Input data-testid="input-fullname" autoComplete="name" placeholder="e.g. Kavitha Reddy" {...field}/></FormControl><FormMessage/></FormItem>}/>}
          <FormField control={form.control} name="email" render={({field})=><FormItem><FormLabel>Email address</FormLabel><FormControl><Input data-testid="input-email" type="email" autoComplete="email" placeholder="you@example.com" {...field}/></FormControl><FormMessage/></FormItem>}/>
          <FormField control={form.control} name="password" render={({field})=><FormItem><FormLabel>Password</FormLabel><FormControl><Input data-testid="input-password" type="password" autoComplete={mode==='login'?'current-password':'new-password'} placeholder="At least 6 characters" {...field}/></FormControl><FormMessage/></FormItem>}/>
          <Button data-testid="button-auth-submit" type="submit" className="mt-2 h-12 w-full rounded-xl bg-emerald-800 font-semibold hover:bg-emerald-900" disabled={form.formState.isSubmitting||loading||!client}>{form.formState.isSubmitting?<><LoaderCircle className="mr-2 animate-spin" size={17}/> Working…</>:mode==='login'?'Sign in to your workspace':'Create account'}<ArrowRight className="ml-auto" size={16}/></Button>
        </form></Form>
        <p className="mt-6 text-center text-xs text-muted-foreground">{mode==='login'?'New to AgriVaanix?':'Already have an account?'} <Link href={mode==='login'?'/register':'/login'} className="font-semibold text-emerald-800 underline-offset-4 hover:underline" data-testid="link-auth-switch">{mode==='login'?'Create an account':'Sign in'}</Link></p>
        {!loading&&!client&&<p role="status" className="mt-4 rounded-lg bg-amber-100 p-3 text-xs text-amber-900">Secure sign-in settings could not be reached. Check your connection and refresh.</p>}
      </div>
    </main>
  </div>;
}

function QueryNotice({ loading, error, retry }: { loading:boolean; error:boolean; retry:()=>void }) {
  if (loading) return <div className="space-y-3" aria-label="Loading"><div className="h-16 animate-pulse rounded-2xl bg-muted"/><div className="h-16 animate-pulse rounded-2xl bg-muted"/><div className="h-16 animate-pulse rounded-2xl bg-muted"/></div>;
  if (error) return <div className="rounded-2xl border border-destructive/20 bg-card p-8 text-center"><p className="font-semibold">We couldn’t load this just now.</p><p className="mt-1 text-sm text-muted-foreground">Check your connection and try again.</p><Button onClick={retry} variant="outline" className="mt-4" data-testid="button-retry"><RotateCcw className="mr-2" size={15}/>Try again</Button></div>;
  return null;
}
function ChatMessage({ message, onSpeak, onStop, speaking }: { message:AdvisoryMessage; onSpeak:(text:string,lang:string)=>void; onStop:()=>void; speaking:boolean }) {
  const assistant=message.role==='assistant';
  return <article data-testid={`message-${message.id}`} className={cx('rise max-w-[820px]',assistant?'mr-auto':'ml-auto')}><div className={cx('rounded-[1.3rem] px-5 py-4 sm:px-6',assistant?'border border-emerald-950/10 bg-card shadow-sm':'bg-emerald-800 text-white')}><div className={cx('mb-3 flex items-center justify-between gap-3 text-[10px] font-semibold uppercase tracking-[.13em]',assistant?'text-emerald-800':'text-emerald-50/65')}><span>{assistant?'AgriVaanix advisor':'You'}{assistant&&message.domain!=='general'&&<span className="ml-2 rounded-full bg-emerald-100 px-2 py-1 text-[9px] normal-case tracking-normal text-emerald-900">{message.domain.replaceAll('_',' ')}</span>}</span><span className="flex items-center gap-2">{fmtDate(message.createdAt)}{assistant&&<button onClick={()=>speaking?onStop():onSpeak(message.content,message.language)} className="rounded-md p-1 hover:bg-emerald-100" aria-label={speaking?'Stop reading':'Read answer aloud'} data-testid={`button-speech-${message.id}`}>{speaking?<VolumeX size={14}/>:<Volume2 size={14}/>}</button>}</span></div>
    <p className={cx('whitespace-pre-wrap text-[14px] leading-7',assistant?'text-foreground':'text-white')}>{message.content}</p>
    {assistant&&message.actionItems?.length>0&&<div className="mt-5 border-t border-emerald-950/10 pt-4"><p className="mb-2 flex items-center gap-2 text-xs font-bold text-emerald-800"><Check size={14}/> What you can do</p><ul className="space-y-2">{message.actionItems.map((item,i)=><li key={i} className="flex gap-2 text-sm leading-6"><span className="mt-2 size-1.5 shrink-0 rounded-full bg-amber-600"/>{item}</li>)}</ul></div>}
    {assistant&&message.safetyNotes?.length>0&&<div className="mt-4 rounded-xl bg-amber-50 px-4 py-3 text-xs leading-5 text-amber-950"><p className="mb-1 flex items-center gap-2 font-bold"><ShieldCheck size={13}/> Please keep in mind</p>{message.safetyNotes.map((note,i)=><p key={i}>{note}</p>)}</div>}
  </div></article>;
}

export function Workspace({ conversationId }: { conversationId?:string }) {
  const queryClient=useQueryClient(); const [,navigate]=useLocation(); const {toast}=useToast();
  const {data:summary,isLoading:summaryLoading,isError:summaryError,refetch:reloadSummary}=useGetDashboardSummary();
  const {data:conversations=[],isLoading:conversationsLoading}=useListConversations();
  const {data:profile}=useGetFarmProfile();
  const conversationQuery=useGetConversation(conversationId||'',{query:{enabled:!!conversationId,queryKey:getGetConversationQueryKey(conversationId||'')}});
  const messagesQuery=useListConversationMessages(conversationId||'',{query:{enabled:!!conversationId,queryKey:getListConversationMessagesQueryKey(conversationId||'')}});
  const createConversation=useCreateConversation(); const sendMessage=useSendAdvisoryMessage();
  const [draft,setDraft]=useState(''); const [pendingUser,setPendingUser]=useState(''); const [recording,setRecording]=useState(false); const [micError,setMicError]=useState('');
  const scrollRef=useRef<HTMLDivElement>(null); const recognitionRef=useRef<{stop:()=>void}|null>(null); const {user}=useAuth();
  const messages=useMemo(()=>messagesQuery.data||conversationQuery.data?.messages||[],[messagesQuery.data,conversationQuery.data?.messages]);
  useEffect(()=>{scrollRef.current?.scrollTo({top:scrollRef.current.scrollHeight,behavior:'smooth'});},[messages.length,pendingUser]);
  const stopSpeech=()=>{if('speechSynthesis'in window)window.speechSynthesis.cancel();};
  const speak=(text:string,lang:string)=>{if(!('speechSynthesis'in window)){toast({title:'Speech is not available',description:'This browser cannot read answers aloud.'});return;}stopSpeech();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=lang==='hi'?'hi-IN':lang==='te'?'te-IN':'en-IN';const speed=Number(localStorage.getItem('agri-speech-speed')||'1');utterance.rate=speed;window.speechSynthesis.speak(utterance);};
  const send=async (value=draft)=>{
    const content=value.trim();if(!content||sendMessage.isPending||createConversation.isPending)return;
    setDraft('');setPendingUser(content);
    try {
      let id=conversationId;
      if(!id){const created=await createConversation.mutateAsync({data:{title:content.slice(0,70)}});id=created.id;await queryClient.invalidateQueries({queryKey:getListConversationsQueryKey()});}
      const exchange=await sendMessage.mutateAsync({id,data:{content}});
      setPendingUser('');
      await Promise.all([queryClient.invalidateQueries({queryKey:getGetConversationQueryKey(id)}),queryClient.invalidateQueries({queryKey:getListConversationMessagesQueryKey(id)}),queryClient.invalidateQueries({queryKey:getListConversationsQueryKey()}),queryClient.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})]);
      if(!conversationId)navigate(`/chat/${id}`);
      const auto=localStorage.getItem('agri-autoplay')==='true';
      if(auto&&exchange.assistantMessage)speak(exchange.assistantMessage.content,exchange.assistantMessage.language);
    } catch(e){setPendingUser('');setDraft(content);toast({title:'Your question wasn’t sent',description:e instanceof Error?e.message:'Check your connection and try again.'});}
  };
  const startVoice=()=>{
    const w=window as Window&{SpeechRecognition?:new()=>any;webkitSpeechRecognition?:new()=>any};
    const Recognition=w.SpeechRecognition||w.webkitSpeechRecognition;
    if(!Recognition){setMicError('Voice input is not supported in this browser. You can type your question instead.');return;}
    const recognition=new Recognition();recognitionRef.current=recognition;recognition.lang=profile?.preferredLanguage==='hi'?'hi-IN':profile?.preferredLanguage==='te'?'te-IN':'en-IN';recognition.interimResults=false;recognition.onresult=(event:any)=>{setDraft((prev)=>`${prev}${prev?' ':''}${event.results[0][0].transcript}`);setRecording(false);setMicError('');};recognition.onerror=()=>{setRecording(false);setMicError('Microphone access failed. Check browser permissions or type your question.');};recognition.onend=()=>setRecording(false);setMicError('');setRecording(true);recognition.start();
  };
  const greetingName=profile?.fullName?.split(' ')[0]||user?.user_metadata?.full_name?.split(' ')[0]||'there';
  const noQueryError=summaryError||conversationQuery.isError||messagesQuery.isError;
  return <AppFrame title={conversationId?(conversationQuery.data?.title||'Your consultation'):'Ask an advisor'} subtitle={conversationId?'A considered answer, grounded in your farm details.':'Practical crop guidance, in your language.'}>
    {!conversationId&&<div className="mb-6 grid gap-4 xl:grid-cols-[1fr_300px]">
      <section className="relative overflow-hidden rounded-[1.6rem] bg-emerald-900 px-6 py-7 text-[#f6f2e7] sm:px-9 sm:py-9"><div className="absolute -right-6 -top-12 size-52 rounded-full border border-amber-100/10"/><div className="absolute -right-1 top-6 size-32 rounded-full border border-amber-100/10"/><div className="relative"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-amber-200">Your farm, in focus</p><h2 className="mt-3 font-serif text-3xl sm:text-[38px]">Good morning, {greetingName}.</h2><p className="mt-2 max-w-lg text-sm leading-6 text-emerald-50/70">What’s happening in your field today? Ask a question and we’ll work through it together.</p>
      <div className="mt-6 flex flex-wrap gap-2">{['What should I plant this season?','Help me identify a pest','How often should I irrigate?'].map((suggestion,i)=><button key={suggestion} onClick={()=>send(suggestion)} disabled={sendMessage.isPending} className="rounded-full border border-white/20 bg-white/[.06] px-3.5 py-2 text-[11px] text-white/90 hover:bg-white/10 disabled:opacity-50" data-testid={`suggestion-${i}`}>{suggestion}</button>)}</div></div></section>
      <section className="rounded-[1.6rem] border border-border bg-card p-5 sm:p-6"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.13em] text-muted-foreground">Season notes</p><Sprout size={17} className="text-emerald-800"/></div>
        {summaryLoading?<div className="mt-5 space-y-3"><div className="h-7 animate-pulse rounded bg-muted"/><div className="h-7 animate-pulse rounded bg-muted"/></div>:summaryError?<button className="mt-4 text-xs text-destructive underline" onClick={()=>reloadSummary()}>Couldn’t load overview. Retry.</button>:<div className="mt-4 grid grid-cols-3 gap-2"><div><p data-testid="metric-consultations" className="font-serif text-3xl text-emerald-900">{summary?.conversationCount??0}</p><p className="mt-1 text-[10px] text-muted-foreground">Conversations</p></div><div><p data-testid="metric-advice" className="font-serif text-3xl text-emerald-900">{summary?.adviceCount??0}</p><p className="mt-1 text-[10px] text-muted-foreground">Advice notes</p></div><div><p data-testid="metric-fields" className="font-serif text-3xl text-emerald-900">{summary?.activeFields??0}</p><p className="mt-1 text-[10px] text-muted-foreground">Farm profile</p></div></div>}
        <Link href="/farm-profile" className="mt-5 flex items-center justify-between rounded-xl bg-[#f1eee3] px-3 py-3 text-xs font-semibold text-emerald-900" data-testid="link-farm-setup"><span className="flex items-center gap-2"><MapPin size={15}/>{profile?.region||'Add your farm details'}</span><ArrowRight size={15}/></Link>
      </section>
    </div>}
    <div className={cx('grid gap-5',!conversationId&&'xl:grid-cols-[1fr_300px]')}>
      <section className="min-h-[420px] overflow-hidden rounded-[1.6rem] border border-border bg-[#faf9f3]">
        <div className="flex items-center justify-between border-b border-border/80 px-5 py-4 sm:px-7"><div><h3 className="font-serif text-xl">{conversationId?'Consultation notes':'Start a conversation'}</h3><p className="mt-1 text-[11px] text-muted-foreground">{profile?.preferredLanguage?`Replies in ${languageNames[profile.preferredLanguage]||'your preferred language'}`:'Set a language in your farm profile for more personal guidance.'}</p></div>{conversationId&&<Link href="/dashboard" className="rounded-lg border border-border px-3 py-2 text-xs font-semibold hover:bg-muted" data-testid="button-new-chat"><Plus size={14} className="mr-1 inline"/>New question</Link>}</div>
        {(conversationId&&noQueryError)&&<QueryNotice loading={false} error retry={()=>{void conversationQuery.refetch();void messagesQuery.refetch();}}/>}
        {conversationId&&conversationQuery.isLoading&&<div className="space-y-4 p-6"><div className="h-20 animate-pulse rounded-xl bg-muted"/><div className="ml-auto h-16 max-w-[60%] animate-pulse rounded-xl bg-muted"/><div className="h-28 max-w-[80%] animate-pulse rounded-xl bg-muted"/></div>}
        {(!conversationId||(!conversationQuery.isLoading&&!noQueryError))&&<div ref={scrollRef} className="flex max-h-[min(65vh,680px)] min-h-[260px] flex-col gap-5 overflow-y-auto px-4 py-5 sm:px-7 sm:py-7" data-testid="conversation-messages">
          {!conversationId&&<div className="m-auto max-w-md py-8 text-center"><div className="mx-auto grid size-14 place-items-center rounded-2xl bg-emerald-100 text-emerald-900"><MessageCircle size={25}/></div><h3 className="mt-4 font-serif text-2xl">What would you like to know?</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Share what you’re seeing, where it’s happening, and what you’ve tried so far.</p></div>}
          {conversationId&&!messages.length&&!messagesQuery.isLoading&&<div className="m-auto py-10 text-center text-sm text-muted-foreground">No messages in this consultation yet. Ask your first question below.</div>}
          {messages.map(message=><ChatMessage key={message.id} message={message} onSpeak={speak} onStop={stopSpeech} speaking={'speechSynthesis'in window&&window.speechSynthesis.speaking}/>)}
          {pendingUser&&<><div className="ml-auto max-w-[80%] rounded-[1.3rem] bg-emerald-800 px-5 py-4 text-sm leading-6 text-white">{pendingUser}</div><div role="status" className="mr-auto flex items-center gap-3 rounded-2xl border border-border bg-card px-4 py-3 text-xs text-muted-foreground"><span className="flex gap-1"><i className="size-1.5 animate-pulse rounded-full bg-emerald-700"/><i className="size-1.5 animate-pulse rounded-full bg-emerald-700 [animation-delay:120ms]"/><i className="size-1.5 animate-pulse rounded-full bg-emerald-700 [animation-delay:240ms]"/></span>Considering your question…</div></>}
        </div>}
        <div className="border-t border-border/80 bg-[#f4f1e7] p-3 sm:p-5"><div className="mx-auto max-w-[900px] rounded-2xl border border-emerald-950/15 bg-card p-2 shadow-sm focus-within:border-emerald-700/50"><textarea value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();void send();}}} placeholder="Ask about a crop, a symptom, or a decision…" rows={2} maxLength={8000} className="max-h-40 min-h-[48px] w-full resize-y bg-transparent px-3 py-2 text-sm leading-6 outline-none placeholder:text-muted-foreground/80" aria-label="Your question" data-testid="input-advisory"/>
          {micError&&<p role="status" className="px-3 pb-2 text-xs text-amber-800">{micError}</p>}<div className="flex items-center justify-between px-1"><div className="flex items-center gap-1"><button onClick={recording?()=>{recognitionRef.current?.stop();setRecording(false);}:startVoice} className={cx('flex items-center gap-1.5 rounded-lg px-2.5 py-2 text-[11px] font-semibold',recording?'bg-rose-100 text-rose-800':'text-muted-foreground hover:bg-muted')} aria-label={recording?'Stop voice input':'Speak your question'} data-testid="button-microphone">{recording?<MicOff size={15}/>:<Mic size={15}/>}<span className="hidden sm:inline">{recording?'Listening':'Speak'}</span></button><span className="hidden text-[10px] text-muted-foreground sm:inline">Enter to send · Shift + Enter for a new line</span></div><Button onClick={()=>void send()} disabled={!draft.trim()||sendMessage.isPending||createConversation.isPending} className="h-9 rounded-xl bg-emerald-800 px-4 text-xs font-semibold hover:bg-emerald-900" data-testid="button-send">{sendMessage.isPending||createConversation.isPending?<LoaderCircle className="mr-2 animate-spin" size={15}/>:<Send className="mr-2" size={14}/>}Send</Button></div></div><p className="mx-auto mt-2 max-w-[900px] px-2 text-[10px] leading-4 text-muted-foreground">Advice is for general guidance. Confirm important treatments and safety decisions with a local agriculture professional.</p></div>
      </section>
      {!conversationId&&<aside className="space-y-5"><section className="rounded-[1.6rem] border border-border bg-card p-5"><div className="flex items-center justify-between"><h3 className="font-serif text-xl">Recent consultations</h3><Link href="/history" className="text-[11px] font-semibold text-emerald-800 hover:underline" data-testid="link-view-history">All notes</Link></div>
        {conversationsLoading?<div className="mt-4 space-y-3"><div className="h-12 animate-pulse rounded bg-muted"/><div className="h-12 animate-pulse rounded bg-muted"/></div>:!conversations.length?<div className="mt-5 rounded-xl bg-[#f4f1e7] p-4 text-center"><FileText className="mx-auto text-emerald-800/50" size={20}/><p className="mt-2 text-xs font-semibold">Your notes start here</p><p className="mt-1 text-[11px] leading-5 text-muted-foreground">Ask your first question and it’ll be saved here.</p></div>:<div className="mt-3 divide-y divide-border">{conversations.slice(0,5).map(c=><Link key={c.id} href={`/chat/${c.id}`} data-testid={`recent-${c.id}`} className="group flex items-center gap-3 py-3"><span className="grid size-9 shrink-0 place-items-center rounded-xl bg-emerald-50 text-emerald-800"><MessageCircle size={16}/></span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-semibold">{c.title}</span><span className="mt-1 block text-[10px] text-muted-foreground">{fmtDate(c.updatedAt)} · {c.messageCount} messages</span></span><ArrowRight size={14} className="text-muted-foreground/50 group-hover:text-emerald-800"/></Link>)}</div>}
      </section>
      <section className="rounded-[1.6rem] bg-[#e8e0cc] p-5"><p className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.15em] text-emerald-800"><Droplets size={14}/> Better answers begin with context</p><p className="mt-3 font-serif text-xl">A little about your field goes a long way.</p><p className="mt-2 text-xs leading-5 text-emerald-950/65">Add your crops, soil and water source to help make future advice more relevant.</p><Link href="/farm-profile" className="mt-4 inline-flex items-center gap-2 text-xs font-bold text-emerald-900" data-testid="link-complete-profile">Complete farm profile <ArrowRight size={14}/></Link></section>
      </aside>}
    </div>
  </AppFrame>;
}

export function HistoryPage() {
  const queryClient=useQueryClient();const {data:conversations=[],isLoading,isError,refetch}=useListConversations();const [search,setSearch]=useState('');const [deleteId,setDeleteId]=useState<string|null>(null);const remove=useDeleteConversation();const {toast}=useToast();const [,navigate]=useLocation();
  const filtered=conversations.filter(c=>c.title.toLowerCase().includes(search.toLowerCase()));
  const deleteConversation=async(id:string)=>{try{await remove.mutateAsync({id});await Promise.all([queryClient.invalidateQueries({queryKey:getListConversationsQueryKey()}),queryClient.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})]);setDeleteId(null);toast({title:'Consultation removed'});}catch(e){toast({title:'Could not remove this consultation',description:e instanceof Error?e.message:'Please try again.'});}};
  return <AppFrame title="My consultations" subtitle="A record of the questions you’ve worked through.">
    <div className="mx-auto max-w-[950px]"><div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.15em] text-emerald-700">Field notes</p><h2 className="mt-2 font-serif text-3xl">Return to a conversation</h2><p className="mt-1 text-sm text-muted-foreground">Your advisory history stays in one place.</p></div><Link href="/dashboard" className="inline-flex items-center justify-center gap-2 rounded-xl bg-emerald-800 px-4 py-3 text-xs font-semibold text-white hover:bg-emerald-900" data-testid="button-new-consultation"><Plus size={15}/> Start a new consultation</Link></div>
      <div className="mb-4 flex items-center gap-3 rounded-xl border border-border bg-card px-4"><FileText className="text-muted-foreground" size={17}/><input type="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find a conversation…" className="h-12 flex-1 bg-transparent text-sm outline-none" data-testid="input-history-search"/><span className="text-[10px] text-muted-foreground">{filtered.length} {filtered.length===1?'note':'notes'}</span></div>
      {isLoading?<QueryNotice loading error={false} retry={()=>{}}/>:isError?<QueryNotice loading={false} error retry={()=>void refetch()}/>:filtered.length===0?<div className="rounded-[1.5rem] border border-dashed border-emerald-950/20 bg-card px-6 py-16 text-center"><div className="mx-auto grid size-14 place-items-center rounded-2xl bg-[#eee9d9] text-emerald-800"><Bookmark size={23}/></div><h3 className="mt-4 font-serif text-2xl">{search?'No matching notes':'Your field notes will appear here'}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{search?'Try another word or clear the search.':'Start a consultation to save useful guidance and find it again when you need it.'}</p>{search?<button onClick={()=>setSearch('')} className="mt-4 text-sm font-semibold text-emerald-800 underline">Clear search</button>:<Link href="/dashboard" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-emerald-800 px-4 py-3 text-xs font-semibold text-white" data-testid="link-first-consultation"><MessageCircle size={15}/> Ask your first question</Link>}</div>:<div className="space-y-3">{filtered.map((c,i)=><article key={c.id} className="group rounded-2xl border border-border bg-card p-4 transition-shadow hover:shadow-sm sm:p-5" data-testid={`history-item-${c.id}`}><div className="flex items-start gap-4"><span className="hidden size-11 shrink-0 place-items-center rounded-xl bg-emerald-50 text-emerald-800 sm:grid"><MessageCircle size={19}/></span><div className="min-w-0 flex-1"><Link href={`/chat/${c.id}`} className="block truncate font-serif text-xl text-emerald-950 hover:text-emerald-800">{c.title}</Link><p className="mt-1 text-xs text-muted-foreground">Updated {fmtDate(c.updatedAt)} <span className="px-1">·</span> {c.messageCount} messages</p></div><button onClick={()=>setDeleteId(c.id)} title="Delete consultation" className="rounded-lg p-2 text-muted-foreground hover:bg-rose-50 hover:text-rose-700" data-testid={`button-delete-${c.id}`}><Trash2 size={16}/></button><Link href={`/chat/${c.id}`} className="hidden items-center gap-1 rounded-lg border border-border px-3 py-2 text-xs font-semibold hover:bg-muted sm:flex" data-testid={`link-open-${c.id}`}>Open <ArrowRight size={14}/></Link></div>{deleteId===c.id&&<div className="mt-4 flex flex-col justify-between gap-3 rounded-xl bg-rose-50 px-4 py-3 sm:flex-row sm:items-center"><p className="text-xs text-rose-950">Delete this conversation and its messages? This cannot be undone.</p><div className="flex gap-2"><button onClick={()=>setDeleteId(null)} className="rounded-lg px-3 py-2 text-xs font-semibold text-rose-900 hover:bg-rose-100" data-testid="button-cancel-delete">Keep it</button><button onClick={()=>void deleteConversation(c.id)} disabled={remove.isPending} className="rounded-lg bg-rose-700 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50" data-testid="button-confirm-delete">{remove.isPending?'Removing…':'Delete permanently'}</button></div></div>}</article>)}</div>}
    </div>
  </AppFrame>;
}

const farmSchema=z.object({fullName:z.string().min(1,'Tell us your name').max(120),region:z.string().min(1,'Add your region').max(160),preferredLanguage:z.enum(['en','hi','te']),landArea:z.coerce.number().min(0,'Area cannot be negative'),landUnit:z.enum(['acres','hectares']),irrigationSource:z.string().min(1,'Add your main water source').max(120),soilType:z.string().min(1,'Choose your soil type').max(120),soilPh:z.preprocess(v=>v===''||v===undefined?null:Number(v),z.number().min(0).max(14).nullable()),primaryCrops:z.string().min(1,'Add at least one crop')});
type FarmValues=z.infer<typeof farmSchema>;
const selectClass="h-11 w-full rounded-lg border border-input bg-card px-3 text-sm text-foreground outline-none focus:ring-2 focus:ring-ring/30";
export function ProfilePage() {
  const qc=useQueryClient();const {data:profile,isLoading,isError,refetch}=useGetFarmProfile();const save=useSaveFarmProfile();const {toast}=useToast();
  const form=useForm<FarmValues>({resolver:zodResolver(farmSchema),defaultValues:{fullName:'',region:'',preferredLanguage:'en',landArea:0,landUnit:'acres',irrigationSource:'',soilType:'',soilPh:null,primaryCrops:''}});
  useEffect(()=>{if(profile)form.reset({...profile,soilPh:profile.soilPh??null,primaryCrops:profile.primaryCrops.join(', ')});},[profile,form]);
  const submit=async(v:FarmValues)=>{const data:FarmProfileInput={...v,primaryCrops:v.primaryCrops.split(',').map(s=>s.trim()).filter(Boolean).slice(0,20)};try{await save.mutateAsync({data});await Promise.all([qc.invalidateQueries({queryKey:getGetFarmProfileQueryKey()}),qc.invalidateQueries({queryKey:getGetDashboardSummaryQueryKey()})]);toast({title:'Farm profile saved',description:'Your details will be ready for your next conversation.'});}catch(e){toast({title:'Could not save your profile',description:e instanceof Error?e.message:'Check your connection and try again.'});}};
  return <AppFrame title="My farm" subtitle="Share a few details so your advice can be more relevant."><div className="mx-auto max-w-[920px]">
    <div className="mb-6 rounded-[1.5rem] bg-emerald-900 p-6 text-white sm:flex sm:items-center sm:justify-between sm:p-7"><div><span className="text-[10px] font-bold uppercase tracking-[.2em] text-amber-200">Your farm, your context</span><h2 className="mt-2 font-serif text-3xl">A little detail. A lot more context.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-emerald-50/70">These details help frame a conversation. You can update them whenever your farm changes.</p></div><span className="mt-5 hidden size-14 place-items-center rounded-2xl bg-amber-200/10 text-amber-200 sm:grid"><Tractor size={27}/></span></div>
    {isLoading?<QueryNotice loading error={false} retry={()=>{}}/>:isError?<QueryNotice loading={false} error retry={()=>void refetch()}/>:<Form {...form}><form onSubmit={form.handleSubmit(submit)} className="space-y-6">
      <section className="rounded-[1.4rem] border border-border bg-card p-5 sm:p-7"><div className="mb-5"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-emerald-700">01 · About you</p><h3 className="mt-1 font-serif text-2xl">Where you farm</h3></div><div className="grid gap-5 sm:grid-cols-2">
        <FormField control={form.control} name="fullName" render={({field})=><FormItem><FormLabel>Your name</FormLabel><FormControl><Input data-testid="input-farm-name" placeholder="Name you go by" {...field}/></FormControl><FormMessage/></FormItem>}/>
        <FormField control={form.control} name="region" render={({field})=><FormItem><FormLabel>Village, district or region</FormLabel><FormControl><Input data-testid="input-region" placeholder="e.g. Guntur, Andhra Pradesh" {...field}/></FormControl><FormMessage/></FormItem>}/>
        <FormField control={form.control} name="preferredLanguage" render={({field})=><FormItem><FormLabel>Preferred advice language</FormLabel><FormControl><select data-testid="select-language" className={selectClass} {...field}><option value="en">English</option><option value="hi">हिन्दी</option><option value="te">తెలుగు</option></select></FormControl><FormMessage/></FormItem>}/>
        <div className="grid grid-cols-[1fr_130px] gap-3"><FormField control={form.control} name="landArea" render={({field})=><FormItem><FormLabel>Farm size</FormLabel><FormControl><Input data-testid="input-land-area" type="number" min="0" step="0.01" placeholder="0" {...field}/></FormControl><FormMessage/></FormItem>}/><FormField control={form.control} name="landUnit" render={({field})=><FormItem><FormLabel>Unit</FormLabel><FormControl><select data-testid="select-land-unit" className={selectClass} {...field}><option value="acres">Acres</option><option value="hectares">Hectares</option></select></FormControl><FormMessage/></FormItem>}/></div>
      </div></section>
      <section className="rounded-[1.4rem] border border-border bg-card p-5 sm:p-7"><div className="mb-5"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-emerald-700">02 · Growing conditions</p><h3 className="mt-1 font-serif text-2xl">What’s in your fields</h3></div><div className="grid gap-5 sm:grid-cols-2">
        <FormField control={form.control} name="irrigationSource" render={({field})=><FormItem><FormLabel>Main irrigation source</FormLabel><FormControl><select data-testid="select-irrigation" className={selectClass} {...field}><option value="">Choose your main source</option><option value="Borewell">Borewell</option><option value="Canal">Canal</option><option value="Rain-fed">Rain-fed</option><option value="Tank or pond">Tank or pond</option><option value="Drip irrigation">Drip irrigation</option><option value="Other">Other</option></select></FormControl><FormMessage/></FormItem>}/>
        <FormField control={form.control} name="soilType" render={({field})=><FormItem><FormLabel>Soil type</FormLabel><FormControl><select data-testid="select-soil" className={selectClass} {...field}><option value="">Choose the closest match</option><option value="Black cotton soil">Black cotton soil</option><option value="Red soil">Red soil</option><option value="Red sandy loam">Red sandy loam</option><option value="Alluvial soil">Alluvial soil</option><option value="Laterite soil">Laterite soil</option><option value="Sandy soil">Sandy soil</option><option value="Not sure">Not sure</option></select></FormControl><FormMessage/></FormItem>}/>
        <FormField control={form.control} name="soilPh" render={({field})=><FormItem><FormLabel>Soil pH <span className="font-normal text-muted-foreground">(if you know it)</span></FormLabel><FormControl><Input data-testid="input-soil-ph" type="number" min="0" max="14" step=".1" placeholder="e.g. 6.8" value={field.value??''} onChange={e=>field.onChange(e.target.value===''?null:Number(e.target.value))}/></FormControl><FormMessage/></FormItem>}/>
        <FormField control={form.control} name="primaryCrops" render={({field})=><FormItem><FormLabel>Main crops</FormLabel><FormControl><Input data-testid="input-crops" placeholder="Cotton, red gram, chilli" {...field}/></FormControl><p className="text-[11px] text-muted-foreground">Separate crops with commas.</p><FormMessage/></FormItem>}/>
      </div></section>
      <div className="flex flex-col justify-between gap-3 rounded-2xl bg-[#e8e2d3] p-4 sm:flex-row sm:items-center sm:px-6"><p className="text-xs leading-5 text-emerald-950/65">Only share what you’re comfortable sharing. Your farm details help personalize advice and can be updated any time.</p><Button data-testid="button-save-profile" type="submit" disabled={save.isPending} className="h-11 shrink-0 rounded-xl bg-emerald-800 px-5 hover:bg-emerald-900">{save.isPending?<LoaderCircle className="mr-2 animate-spin" size={16}/>:<Check className="mr-2" size={16}/>}Save farm profile</Button></div>
    </form></Form>}
  </div></AppFrame>;
}

export function SettingsPage() {
  const qc=useQueryClient();const {data:profile,isLoading,isError,refetch}=useGetFarmProfile();const saveProfile=useSaveFarmProfile();const {toast}=useToast();
  const [autoplay,setAutoplay]=useState(()=>localStorage.getItem('agri-autoplay')==='true');const [speed,setSpeed]=useState(()=>Number(localStorage.getItem('agri-speech-speed')||'1'));
  const setAuto=(value:boolean)=>{setAutoplay(value);localStorage.setItem('agri-autoplay',String(value));};
  const setLanguage=async(value:'en'|'hi'|'te')=>{if(!profile){toast({title:'Add your farm profile first',description:'Your language preference is saved with your farm details.'});return;}try{await saveProfile.mutateAsync({data:{fullName:profile.fullName,region:profile.region,preferredLanguage:value,landArea:profile.landArea,landUnit:profile.landUnit as 'acres'|'hectares',irrigationSource:profile.irrigationSource,soilType:profile.soilType,soilPh:profile.soilPh,primaryCrops:profile.primaryCrops}});await qc.invalidateQueries({queryKey:getGetFarmProfileQueryKey()});toast({title:'Language preference saved',description:`Your farm profile now uses ${languageNames[value]}.`});}catch(e){toast({title:'Could not update language',description:e instanceof Error?e.message:'Please try again.'});}};
  const stop=()=>{if('speechSynthesis'in window)window.speechSynthesis.cancel();};
  return <AppFrame title="Preferences" subtitle="Set up a workspace that works for you."><div className="mx-auto max-w-[850px]">
    <div className="mb-7"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-emerald-700">Your workspace</p><h2 className="mt-2 font-serif text-3xl">The way you like to listen</h2><p className="mt-2 text-sm text-muted-foreground">Speech controls are saved on this device. Advice language is stored with your farm profile.</p></div>
    {isLoading?<QueryNotice loading error={false} retry={()=>{}}/>:isError&&<QueryNotice loading={false} error retry={()=>void refetch()}/>}
    <section className="mb-4 rounded-[1.4rem] border border-border bg-card p-5 sm:p-7"><div className="flex items-start gap-4"><span className="grid size-11 shrink-0 place-items-center rounded-xl bg-emerald-50 text-emerald-800"><Languages size={20}/></span><div className="flex-1"><h3 className="font-serif text-xl">Advice language</h3><p className="mt-1 max-w-lg text-xs leading-5 text-muted-foreground">Choose the language you’re most comfortable using for farm advice.</p><div className="mt-4 grid gap-2 sm:grid-cols-3">{(['en','hi','te'] as const).map(code=><button key={code} onClick={()=>void setLanguage(code)} disabled={!profile||saveProfile.isPending||isLoading} data-testid={`language-${code}`} className={cx('rounded-xl border px-4 py-3 text-left text-sm font-semibold transition-colors',profile?.preferredLanguage===code?'border-emerald-800 bg-emerald-50 text-emerald-900':'border-border hover:bg-muted')}><span>{languageNames[code]}</span>{profile?.preferredLanguage===code&&<Check className="float-right mt-0.5" size={15}/>}</button>)}</div>{!profile&&!isLoading&&<Link href="/farm-profile" className="mt-3 inline-flex text-xs font-semibold text-emerald-800 underline">Set up your farm profile first</Link>}</div></div></section>
    <section className="mb-4 rounded-[1.4rem] border border-border bg-card p-5 sm:p-7"><div className="flex items-start gap-4"><span className="grid size-11 shrink-0 place-items-center rounded-xl bg-amber-100 text-amber-900"><Volume2 size={20}/></span><div className="flex-1"><h3 className="font-serif text-xl">Read answers aloud</h3><p className="mt-1 max-w-lg text-xs leading-5 text-muted-foreground">Hear advisory replies spoken using your browser’s available voice.</p><button role="switch" aria-checked={autoplay} onClick={()=>setAuto(!autoplay)} className={cx('mt-4 flex w-full items-center justify-between rounded-xl border px-4 py-3 text-left',autoplay?'border-emerald-700/30 bg-emerald-50':'border-border hover:bg-muted')} data-testid="toggle-autoplay"><span><span className="block text-sm font-semibold">{autoplay?'Automatic playback is on':'Automatic playback is off'}</span><span className="mt-1 block text-[11px] text-muted-foreground">New answers will {autoplay?'be read aloud':'not play automatically'}.</span></span><span className={cx('relative h-6 w-11 rounded-full transition-colors',autoplay?'bg-emerald-700':'bg-stone-300')}><span className={cx('absolute top-1 size-4 rounded-full bg-white transition-transform',autoplay?'translate-x-6':'translate-x-1')}/></span></button>
        <div className="mt-5"><div className="flex items-center justify-between"><label htmlFor="speech-speed" className="text-xs font-semibold">Speech speed</label><span className="rounded-md bg-muted px-2 py-1 font-mono text-[11px]" data-testid="status-speech-speed">{speed.toFixed(1)}×</span></div><input id="speech-speed" data-testid="input-speech-speed" type="range" min="0.7" max="1.4" step="0.1" value={speed} onChange={e=>{const n=Number(e.target.value);setSpeed(n);localStorage.setItem('agri-speech-speed',String(n));}} className="mt-3 w-full accent-emerald-800"/><div className="flex justify-between text-[10px] text-muted-foreground"><span>Slower</span><span>Faster</span></div></div>
        <button onClick={()=>{if(!('speechSynthesis'in window)){toast({title:'Speech not supported',description:'Try a newer browser with speech support.'});return;}stop();const u=new SpeechSynthesisUtterance('This is a sample of your selected speech speed.');u.rate=speed;u.lang=profile?.preferredLanguage==='hi'?'hi-IN':profile?.preferredLanguage==='te'?'te-IN':'en-IN';window.speechSynthesis.speak(u);}} className="mt-4 inline-flex items-center gap-2 rounded-lg border border-border px-3 py-2 text-xs font-semibold hover:bg-muted" data-testid="button-test-speech"><AudioLines size={15}/> Test voice</button>
      </div></div></section>
    <section className="flex flex-col justify-between gap-4 rounded-[1.4rem] bg-[#e8e2d3] p-5 sm:flex-row sm:items-center sm:px-7"><div><h3 className="font-serif text-xl">Browser compatibility</h3><p className="mt-1 text-xs leading-5 text-emerald-950/65">Voice input and audio playback depend on browser support and microphone permissions. You can always type and read responses.</p></div><span className="inline-flex shrink-0 items-center gap-2 text-[11px] font-semibold text-emerald-800"><ShieldCheck size={16}/> Your preferences stay on this device</span></section>
  </div></AppFrame>;
}

export function HelpPage() {
  const [open,setOpen]=useState('ask');const topics=[
    {id:'ask',icon:MessageCircle,title:'Ask a useful question',body:'Tell us what you’re growing and what you’re seeing. Include when it started, which part of the field is affected, recent weather or watering, and anything you have already tried. One focused question at a time makes it easier to work through next steps.'},
    {id:'voice',icon:AudioLines,title:'Use voice in the field',body:'Tap Speak beside the message box and allow microphone access when your browser asks. Say your question in your preferred language; the recognized words appear in the box so you can review them before sending. Voice support varies by browser. Typing is always available.'},
    {id:'listen',icon:Headphones,title:'Listen to an answer',body:'Use the speaker control on an advisory reply to read it aloud. In Preferences, choose automatic playback and adjust the reading speed. Your device and browser determine which voices are available. Stop playback any time with the speaker control or your device controls.'},
    {id:'farm',icon:Tractor,title:'Keep your farm details current',body:'Your region, soil, water source and crops provide helpful context. Update your profile when your crop plan or conditions change. You can leave fields blank when you are unsure; do not guess a soil pH.'},
    {id:'safety',icon:ShieldCheck,title:'Use advice safely',body:'Advisory guidance is a starting point, not a substitute for on-site inspection or official instructions. Follow product labels, local regulations and protective-equipment guidance. For severe crop loss, suspected poisoning, or urgent pest spread, contact your local agriculture officer or extension service.'},
  ];
  return <AppFrame title="Help & guidance" subtitle="Small pointers for getting the most from your workspace."><div className="mx-auto max-w-[980px]">
    <div className="mb-7 rounded-[1.6rem] bg-[#e7dfca] p-6 sm:p-9"><div className="flex items-start justify-between gap-5"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-emerald-800">A helpful place to begin</p><h2 className="mt-3 max-w-xl font-serif text-4xl leading-tight">Good questions grow<br/><span className="italic text-emerald-700">better decisions.</span></h2><p className="mt-3 max-w-xl text-sm leading-6 text-emerald-950/65">Here are a few simple ways to make each conversation useful and safe.</p></div><div className="hidden size-16 shrink-0 place-items-center rounded-2xl bg-emerald-900 text-amber-200 sm:grid"><CircleHelp size={29}/></div></div></div>
    <div className="grid gap-6 lg:grid-cols-[1fr_270px]"><div className="space-y-3">{topics.map(({id,icon:Icon,title,body})=><section key={id} className="overflow-hidden rounded-2xl border border-border bg-card"><button onClick={()=>setOpen(open===id?'':id)} aria-expanded={open===id} className="flex w-full items-center gap-4 px-5 py-4 text-left" data-testid={`help-${id}`}><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-emerald-50 text-emerald-800"><Icon size={18}/></span><span className="flex-1 font-serif text-lg">{title}</span><ChevronDown className={cx('text-muted-foreground transition-transform',open===id&&'rotate-180')} size={17}/></button>{open===id&&<p className="px-5 pb-5 pl-[4.75rem] text-sm leading-6 text-muted-foreground">{body}</p>}</section>)}</div>
      <aside className="space-y-4"><div className="rounded-2xl bg-emerald-900 p-5 text-white"><p className="text-[10px] font-bold uppercase tracking-[.17em] text-amber-200">In a hurry?</p><h3 className="mt-2 font-serif text-2xl">Ask your question</h3><p className="mt-2 text-xs leading-5 text-emerald-50/65">Start with what’s happening in your field.</p><Link href="/dashboard" className="mt-5 flex items-center justify-between rounded-xl bg-amber-200 px-4 py-3 text-xs font-bold text-emerald-950" data-testid="link-help-ask">Open advisor <ArrowRight size={15}/></Link></div><div className="rounded-2xl border border-border bg-card p-5"><p className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck size={16} className="text-emerald-800"/> Need on-site help?</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Contact a local agriculture extension officer for urgent crop damage, disease outbreaks or treatment safety.</p></div><div className="rounded-2xl border border-border bg-card p-5"><p className="flex items-center gap-2 text-sm font-semibold"><Waves size={16} className="text-emerald-800"/> Connection interrupted?</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Your typed question stays in the box if sending fails. Check your connection and retry when you’re back online.</p></div></aside></div>
  </div></AppFrame>;
}
